INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM202ZNXY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'The equation $y = 1.7x + 23.4$ models the relationship between the number of weeks, $x$, since a sapling was planted and the sapling''s height, $y$, in centimeters. According to the model, what does the number $1.7$ represent?', NULL, $lyceon_json$[{"key":"A","text":"The sapling's initial height, in centimeters, when it was planted"},{"key":"B","text":"The predicted height of the sapling, in centimeters, after $1.7$ weeks"},{"key":"C","text":"The predicted increase in the sapling's height, in centimeters, for each additional week after planting"},{"key":"D","text":"The predicted total height of the sapling, in centimeters, after exactly one week"}]$lyceon_json$::jsonb, 'C', NULL, E'In the equation $y = 1.7x + 23.4$, the coefficient $1.7$ is the slope, which represents the rate of change: the sapling''s height increases by $1.7$ centimeters for each additional week. The initial height when planted ($x = 0$) is the $y$-intercept, $23.4$ centimeters, not $1.7$. The value $1.7$ is not a time measurement, so interpreting it as a number of weeks is incorrect. The total height after one week is $1.7(1) + 23.4 = 25.1$ centimeters, not $1.7$ alone.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20IVM2D', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A printing company charges a setup fee of $47$ dollars plus $0.12$ dollars per page for the first $500$ pages and $0.08$ dollars per page for each additional page beyond $500$. A customer paid a total of $139$ dollars. How many pages did the customer print?', NULL, $lyceon_json$[{"key":"A","text":"$767$"},{"key":"B","text":"$900$"},{"key":"C","text":"$1{,}025$"},{"key":"D","text":"$1{,}150$"}]$lyceon_json$::jsonb, 'B', NULL, E'The cost for the first $500$ pages is $47 + 500(0.12) = 47 + 60 = 107$ dollars. The remaining cost is $139 - 107 = 32$ dollars, charged at $0.08$ per page for pages beyond $500$. This gives $32 \\div 0.08 = 400$ additional pages, so the total is $500 + 400 = 900$ pages. The value $767$ results from ignoring the tiered pricing and using a flat rate of $0.12$: $(139 - 47) \\div 0.12 \\approx 767$. The value $1{,}025$ comes from an arithmetic error in the subtraction or division steps. The value $1{,}150$ results from using a flat rate of $0.08$ for all pages: $(139 - 47) \\div 0.08 = 1{,}150$, which ignores that the first $500$ pages are charged at $0.12$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20R0YG2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'A circle in the $xy$-plane has the equation $x^2 + y^2 - 22x + 16y + 92 = 0$. The center of the circle is at $(h, k)$. What is the value of $h + k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Completing the square for $x$: $x^2 - 22x = (x - 11)^2 - 121$. Completing the square for $y$: $y^2 + 16y = (y + 8)^2 - 64$. Substituting: $(x - 11)^2 - 121 + (y + 8)^2 - 64 + 92 = 0$, so $(x - 11)^2 + (y + 8)^2 = 93$. The center is $(11, -8)$, giving $h + k = 11 + (-8) = 3$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21HIXE4', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'What value of $x$ satisfies the equation $11x + 19 = 85$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$\\frac{85}{11}$"},{"key":"D","text":"$\\frac{104}{11}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting $19$ from both sides gives $11x = 66$, and dividing by $11$ gives $x = 6$. The value $-6$ results from a sign error when dividing. The value $\\frac{85}{11}$ comes from dividing $85$ by $11$ without first subtracting $19$. The value $\\frac{104}{11}$ comes from incorrectly adding $19$ to $85$ instead of subtracting.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21QBNII', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A pyramid with a square base is inscribed inside a rectangular box so that the pyramid and the box share the same square base, and the apex of the pyramid touches the top face of the box. The box has a square base with side length $s$ and height $12$. If the volume of the space inside the box but outside the pyramid is $392$ cubic inches, what is the value of $s$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$7\\sqrt{2}$"},{"key":"C","text":"$14$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'A', NULL, E'The volume of the box is $s^2 \\cdot 12 = 12s^2$. The volume of the pyramid is $\\frac{1}{3}s^2 \\cdot 12 = 4s^2$. The space between them has volume $12s^2 - 4s^2 = 8s^2$. Setting $8s^2 = 392$ gives $s^2 = 49$, so $s = 7$. The value $7\\sqrt{2}$ arises from using $\\frac{1}{3}$ of the box volume instead of $\\frac{2}{3}$, yielding $4s^2 = 392$ and $s^2 = 98$. The value $14$ results from a division error such as $s^2 = 392 / 2 = 196$. The value $49$ gives $s^2$ rather than $s$, stopping one step too early.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM220OGB8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a linear relationship between the number of hours spent practicing piano, $x$, and the number of mistakes made during a recital, $y$. The line of best fit is $y = -3x + 41$. What is the predicted number of mistakes for a student who practiced $9$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$32$"},{"key":"B","text":"$27$"},{"key":"C","text":"$68$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'D', NULL, E'Substituting $x = 9$: $y = -3(9) + 41 = -27 + 41 = 14$. The value $32$ results from substituting $x = 3$ instead of $x = 9$ ($-3(3) + 41 = 32$). The value $27$ results from computing only $|-3 \\times 9| = 27$ without adding the intercept. The value $68$ results from ignoring the negative sign on the slope and computing $3(9) + 41 = 68$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2218XBL', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3x^2 + 7x - 2x^2 + 4x - 9$?', NULL, $lyceon_json$[{"key":"A","text":"$x^2 + 11x - 9$"},{"key":"B","text":"$5x^2 + 11x - 9$"},{"key":"C","text":"$x^2 + 3x - 9$"},{"key":"D","text":"$x^2 + 11x + 9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Combining like terms: $3x^2 - 2x^2 = x^2$ and $7x + 4x = 11x$, giving $x^2 + 11x - 9$. The distractor $5x^2 + 11x - 9$ results from adding the $x^2$ coefficients ($3 + 2 = 5$) instead of subtracting. The distractor $x^2 + 3x - 9$ results from subtracting the $x$ coefficients ($7 - 4 = 3$) instead of adding them. The distractor $x^2 + 11x + 9$ incorrectly changes the sign of the constant from $-9$ to $+9$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23JP3NP', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'For what positive value of $k$ does the equation $x^2 + kx + 49 = 0$ have exactly one real solution?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'A quadratic equation $ax^2 + bx + c = 0$ has exactly one real solution when its discriminant equals zero: $b^2 - 4ac = 0$. Here $a = 1$, $b = k$, and $c = 49$, so $k^2 - 4(1)(49) = 0$, which gives $k^2 = 196$. Since $k$ must be positive, $k = 14$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24CH5QW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collected data on the number of hours of sunlight, $x$, and the daily energy output, $y$, in kilowatt-hours, of a solar panel installation over $14$ days. The line of best fit for the data is $y = 4.3x - 7.1$. On a day with $11.5$ hours of sunlight, the actual energy output was $39.8$ kilowatt-hours. What is the residual for this observation?', NULL, $lyceon_json$[{"key":"A","text":"$-2.55$"},{"key":"B","text":"$2.55$"},{"key":"C","text":"$-9.65$"},{"key":"D","text":"$42.35$"}]$lyceon_json$::jsonb, 'A', NULL, E'The predicted value is $y = 4.3(11.5) - 7.1 = 49.45 - 7.1 = 42.35$ kilowatt-hours. The residual is actual minus predicted: $39.8 - 42.35 = -2.55$. The value $2.55$ reverses the subtraction order (predicted minus actual), producing the wrong sign. The value $-9.65$ results from omitting the intercept in the prediction, computing $39.8 - 4.3(11.5) = 39.8 - 49.45 = -9.65$. The value $42.35$ is the predicted output itself, not the residual.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM251O9X0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $38$ centimeters. What is the circumference, in centimeters, of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$19\\pi$"},{"key":"B","text":"$38\\pi$"},{"key":"C","text":"$76\\pi$"},{"key":"D","text":"$361\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Therefore $C = 38\\pi$. The value $19\\pi$ results from using the radius ($19$) instead of the diameter in the circumference formula. The value $76\\pi$ incorrectly doubles the diameter before multiplying by $\\pi$, as if the formula were $2\\pi d$. The value $361\\pi$ computes $\\pi r^2 = \\pi(19)^2 = 361\\pi$, which is the area, not the circumference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25GBKUC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random samples are taken from the same population. Sample $X$ has $150$ observations with a sample proportion of $0.42$ and a margin of error of $\\pm 7.9\\%$. Sample $Y$ has $600$ observations with a sample proportion of $0.38$ and a margin of error of $\\pm 3.9\\%$. Which of the following statements is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"The population proportion is closer to $0.42$ than to $0.38$ because Sample $X$ was collected first."},{"key":"B","text":"The confidence intervals from both samples overlap, so the results are consistent with each other."},{"key":"C","text":"Sample $X$ is more reliable because its sample proportion is higher."},{"key":"D","text":"The population proportion is exactly $0.38$ because Sample $Y$ has a smaller margin of error."}]$lyceon_json$::jsonb, 'B', NULL, E'Sample $X$ gives a confidence interval of approximately $0.341$ to $0.499$, and Sample $Y$ gives approximately $0.341$ to $0.419$. These intervals overlap substantially, meaning the two samples are consistent with each other and with a range of plausible population proportions. The order of sample collection does not determine which estimate is closer to the true value. A higher sample proportion does not make a sample more reliable; reliability depends on sample size and methodology. A smaller margin of error makes an estimate more precise, but the sample proportion is still an estimate, not the exact population value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25JZO3W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A factory packages spice blends. The ratio of cumin to paprika to turmeric in the blend is $5:3:2$ by weight. The factory has $87$ ounces of paprika available and unlimited supplies of cumin and turmeric. Each package contains $6$ ounces of the blend. How many complete packages can the factory fill?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '48', ARRAY['48'], E'The total ratio parts are $5 + 3 + 2 = 10$. Paprika accounts for $\\frac{3}{10}$ of the blend. With $87$ ounces of paprika, the maximum total blend is $87 \\times \\frac{10}{3} = 290$ ounces. Each package holds $6$ ounces, so the number of complete packages is $\\left\\lfloor \\frac{290}{6} \\right\\rfloor = \\left\\lfloor 48.\\overline{3} \\right\\rfloor = 48$. A common error is using $\\frac{3}{8}$ instead of $\\frac{3}{10}$ by forgetting to include turmeric in the total, or failing to round down to a whole number of packages.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25N4TRR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'The base of a triangular prism is a right triangle with legs of length $6$ and $11$. If the height of the prism is $8$, what is the volume of the prism?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '264', ARRAY['264'], E'The area of the triangular base is $\\frac{1}{2}(6)(11) = 33$. The volume of a prism is the base area times the height: $33 \\times 8 = 264$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2672ZIU', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'In the $xy$-plane, the graph of $7x - 4y = k$ passes through the point of intersection of the lines $2x + 3y = 19$ and $4x - y = 3$. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$6$"},{"key":"C","text":"$23$"},{"key":"D","text":"$34$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, find the intersection of $2x + 3y = 19$ and $4x - y = 3$. From the second equation, $y = 4x - 3$. Substituting into the first: $2x + 3(4x - 3) = 19$, which gives $2x + 12x - 9 = 19$, so $14x = 28$ and $x = 2$. Then $y = 4(2) - 3 = 5$. The intersection point is $(2, 5)$. Substituting into $7x - 4y = k$: $k = 7(2) - 4(5) = 14 - 20 = -6$. The value $6$ results from dropping the negative sign. The value $23$ comes from swapping the intersection coordinates and computing $7(5) - 4(3) = 35 - 12 = 23$. The value $34$ results from computing $7(2) + 4(5) = 14 + 20 = 34$, using addition instead of subtraction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26IC10A', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $400$ employees at a large company and finds that $37\\%$ have used the company''s wellness program. The margin of error for this estimate is $\\pm 4.7\\%$. The researcher wants to reduce the margin of error to $\\pm 2.35\\%$. Which of the following changes would achieve this?', NULL, $lyceon_json$[{"key":"A","text":"Doubling the sample size to $800$ employees"},{"key":"B","text":"Quadrupling the sample size to $1{,}600$ employees"},{"key":"C","text":"Halving the sample size to $200$ employees"},{"key":"D","text":"Surveying only employees who have used the wellness program"}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is proportional to $\\frac{1}{\\sqrt{n}}$. To cut the margin of error in half (from $4.7\\%$ to $2.35\\%$), the sample size must be multiplied by $4$, giving $400 \\times 4 = 1{,}600$. Doubling the sample size to $800$ would only reduce the margin of error by a factor of $\\sqrt{2} \\approx 1.41$, not by half. Halving the sample size would increase the margin of error, moving in the wrong direction. Surveying only wellness program users would introduce selection bias and would not produce a valid estimate for all employees.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM270HLKC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f(x) = -2(x + 5)^2 + 18$ has its graph reflected over the $x$-axis and then shifted $3$ units to the right, producing the function $g(x)$. What is the $x$-coordinate of the vertex of $g$?', NULL, $lyceon_json$[{"key":"A","text":"$-8$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$-2$"},{"key":"D","text":"$2$"}]$lyceon_json$::jsonb, 'C', NULL, E'The vertex of $f(x) = -2(x + 5)^2 + 18$ is at $(-5, 18)$. Reflecting over the $x$-axis gives $-f(x) = 2(x + 5)^2 - 18$, which has its vertex at $(-5, -18)$; the reflection does not change the $x$-coordinate. Shifting $3$ units to the right replaces $x$ with $x - 3$, yielding $g(x) = 2(x + 2)^2 - 18$ with vertex at $(-2, -18)$. The $x$-coordinate is $-2$. The distractor $-8$ results from shifting left instead of right ($-5 - 3 = -8$). The distractor $-5$ results from applying only the reflection and ignoring the horizontal shift. The distractor $2$ results from incorrectly reading the original vertex as $(5, 18)$ and then shifting to $5 - 3 = 2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27JHSYB', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'Given the system of inequalities $y \\leq -\\frac{3}{4}x + 9$ and $y \\geq \\frac{2}{5}x - 1$, what is the greatest integer value of $x$ for which there exists a value of $y$ satisfying both inequalities simultaneously?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'For both inequalities to have a common $y$-value at a given $x$, the upper bound must be at least as large as the lower bound: $-\\frac{3}{4}x + 9 \\geq \\frac{2}{5}x - 1$. Adding $1$ to both sides and adding $\\frac{3}{4}x$ to both sides gives $10 \\geq \\frac{2}{5}x + \\frac{3}{4}x$. Finding a common denominator: $\\frac{2}{5}x + \\frac{3}{4}x = \\frac{8}{20}x + \\frac{15}{20}x = \\frac{23}{20}x$. So $10 \\geq \\frac{23}{20}x$, which gives $x \\leq \\frac{200}{23} \\approx 8.696$. The greatest integer value is $8$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27TXDGO', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'The equation $5x - 3y = 39$ relates two variables $x$ and $y$. If $y$ increases by $10$, by how much must $x$ increase so that the equation remains true?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$10$"},{"key":"C","text":"$\\dfrac{50}{3}$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'A', NULL, E'Replacing $y$ with $y + 10$ decreases the left side by $3(10) = 30$ because of the $-3y$ term. To compensate, $5x$ must increase by $30$, so $x$ must increase by $30 \\div 5 = 6$. The value $10$ incorrectly assumes $x$ changes by the same amount as $y$. The value $\\dfrac{50}{3}$ comes from dividing $5 \\times 10 = 50$ by $3$ instead of correctly computing $3 \\times 10 = 30$ divided by $5$. The value $15$ results from multiplying the change in $y$ by $\\dfrac{3}{2}$ rather than $\\dfrac{3}{5}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29Y55L7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one of the acute angles measures $30°$ and the hypotenuse has length $26$. What is the length of the side opposite the $30°$ angle?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$13\\sqrt{3}$"},{"key":"C","text":"$26\\sqrt{3}$"},{"key":"D","text":"$\\frac{26}{\\sqrt{3}}$"}]$lyceon_json$::jsonb, 'A', NULL, E'In a $30°$-$60°$-$90°$ triangle, the side opposite the $30°$ angle is half the hypotenuse. Therefore the length is $\\frac{26}{2} = 13$. The value $13\\sqrt{3}$ is the side opposite the $60°$ angle, not the $30°$ angle. The value $26\\sqrt{3}$ incorrectly multiplies the hypotenuse by $\\sqrt{3}$. The value $\\frac{26}{\\sqrt{3}}$ divides by $\\sqrt{3}$ instead of by $2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AEVT69', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ students found that $74$ play basketball, $53$ play volleyball, and $19$ play both sports. If a student is chosen at random from those who play basketball, what is the probability that the student also plays volleyball?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{200}$"},{"key":"B","text":"$\\frac{19}{74}$"},{"key":"C","text":"$\\frac{19}{53}$"},{"key":"D","text":"$\\frac{53}{74}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the student plays basketball, the sample space is the $74$ basketball players. Of these, $19$ also play volleyball, so the probability is $\\frac{19}{74}$. Using $\\frac{19}{200}$ incorrectly uses the total number of students as the denominator instead of conditioning on basketball players. Using $\\frac{19}{53}$ incorrectly conditions on volleyball players instead of basketball players. Using $\\frac{53}{74}$ incorrectly places all volleyball players in the numerator rather than only those who also play basketball.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ARMGOZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A dataset has the values: $11, 15, 18, 22, 22, 25, 29, 33$. If the value $33$ is replaced by $61$, which of the following measures of the dataset changes?', NULL, $lyceon_json$[{"key":"A","text":"Mode"},{"key":"B","text":"Range"},{"key":"C","text":"Median"},{"key":"D","text":"Both the median and the range"}]$lyceon_json$::jsonb, 'B', NULL, E'Original range: $33 - 11 = 22$. New range: $61 - 11 = 50$. The range changes. The mode is $22$ in both cases (it appears twice and is unaffected by replacing $33$). The median is the average of the $4$th and $5$th values; both before and after the replacement, these are $22$ and $22$, giving a median of $22$. Since only the range changes, the answer that states both the median and the range change is incorrect because the median remains $22$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CK3Z3B', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'Tickets for a local concert cost $17$ dollars each for adults and $11$ dollars each for children. A group purchases $9$ tickets for a total of $129$ dollars. How many adult tickets did the group purchase?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $a$ be the number of adult tickets and $c$ be the number of children''s tickets. The system is $a + c = 9$ and $17a + 11c = 129$. Substituting $c = 9 - a$ into the second equation gives $17a + 11(9 - a) = 129$, which simplifies to $17a + 99 - 11a = 129$, so $6a = 30$ and $a = 5$. The answer $4$ corresponds to the number of children''s tickets, not adult tickets. The answer $6$ results from an arithmetic error when computing $129 - 99$. The answer $7$ comes from incorrectly dividing the total cost by the adult ticket price and rounding.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CSBMZE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $9$ red marbles, $14$ blue marbles, and $4$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{14}{27}$"},{"key":"B","text":"$\\frac{14}{23}$"},{"key":"C","text":"$\\frac{9}{27}$"},{"key":"D","text":"$\\frac{4}{27}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of marbles is $9 + 14 + 4 = 27$. The probability of selecting a blue marble is $\\frac{14}{27}$. The value $\\frac{14}{23}$ uses an incorrect total of $23$ by omitting the green marbles. The value $\\frac{9}{27}$ gives the probability of selecting red, not blue. The value $\\frac{4}{27}$ gives the probability of selecting green, not blue.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ELCL69', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A store charges $13$ dollars for each shirt plus a flat shipping fee of $9$ dollars per order. A customer wants to spend no more than $74$ dollars total. What is the maximum number of shirts the customer can buy?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'The total cost for $s$ shirts is $13s + 9$. Setting up the inequality $13s + 9 \\leq 74$ and subtracting $9$ from both sides gives $13s \\leq 65$. Dividing both sides by $13$ gives $s \\leq 5$. Since the number of shirts must be a whole number, the maximum is $5$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ER9DZ1', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A research station records temperature at two altitudes. At $1{,}500$ meters, the temperature is $7.2$ degrees Celsius, and at $3{,}900$ meters, the temperature is $-4.8$ degrees Celsius. Assuming temperature is a linear function of altitude, at what altitude, in meters, would the temperature be $0$ degrees Celsius?', NULL, $lyceon_json$[{"key":"A","text":"$2{,}460$"},{"key":"B","text":"$2{,}700$"},{"key":"C","text":"$2{,}940$"},{"key":"D","text":"$3{,}180$"}]$lyceon_json$::jsonb, 'C', NULL, E'The slope of temperature versus altitude is $\\dfrac{-4.8 - 7.2}{3900 - 1500} = \\dfrac{-12}{2400} = -0.005$ degrees per meter. Using the point $(1500, 7.2)$ and setting temperature to $0$: $0 = 7.2 - 0.005(a - 1500)$, so $0.005(a - 1500) = 7.2$, giving $a - 1500 = 1440$ and $a = 2940$ meters. The value $2{,}460$ results from using the magnitude of $-4.8$ instead of $7.2$ in the calculation: $4.8 \\div 0.005 = 960$, then $1500 + 960 = 2460$. The value $2{,}700$ comes from simply averaging the two altitudes: $(1500 + 3900) \\div 2 = 2700$, which ignores the asymmetry of the temperature values. The value $3{,}180$ arises from a computational error in dividing $7.2$ by $0.005$, obtaining $1680$ instead of $1440$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FONUC0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangle has a length of $13$ meters and a width of $7$ meters. What is the area, in square meters, of the rectangle?', NULL, $lyceon_json$[{"key":"A","text":"$40$"},{"key":"B","text":"$78$"},{"key":"C","text":"$91$"},{"key":"D","text":"$104$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a rectangle is length times width: $13 \\times 7 = 91$ square meters. The value $40$ is the perimeter $2(13 + 7) = 40$, not the area. The value $78$ results from computing $13 \\times 6$ instead of $13 \\times 7$. The value $104$ results from computing $13 \\times 8$ instead of $13 \\times 7$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G2FJVV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The mean of a dataset of $11$ values is $57$. When the smallest value and the largest value are removed, the mean of the remaining $9$ values is $59$. If the smallest value in the original dataset is $13$, what is the largest value?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '83', ARRAY['83'], E'The sum of all $11$ values is $11 \\times 57 = 627$. The sum of the remaining $9$ values is $9 \\times 59 = 531$. Therefore, the sum of the smallest and largest values is $627 - 531 = 96$. Since the smallest value is $13$, the largest value is $96 - 13 = 83$. A common error is computing $11 \\times 59 - 9 \\times 57$ (reversing which mean corresponds to which count), or forgetting to subtract the smallest value from the sum of the two extremes.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G6WDPZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g(x) = a \\cdot 2^x$ passes through the point $(4, 112)$. What is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$28$"},{"key":"C","text":"$14$"},{"key":"D","text":"$56$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting the point $(4, 112)$ into $g(x) = a \\cdot 2^x$ gives $112 = a \\cdot 2^4 = 16a$, so $a = \\frac{112}{16} = 7$. The distractor $28$ results from dividing $112$ by $4$ (the exponent) instead of by $2^4 = 16$. The distractor $14$ results from dividing $112$ by $8$, which would be $2^3$ rather than $2^4$. The distractor $56$ results from dividing $112$ by $2$ instead of $2^4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HI5BSH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages, in years, of $7$ participants in a community gardening workshop are: $22, 29, 34, 41, 48, 53, 67$. What is the median age of the participants?', NULL, $lyceon_json$[{"key":"A","text":"$41$"},{"key":"B","text":"$42$"},{"key":"C","text":"$37.5$"},{"key":"D","text":"$44.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'With $7$ values listed in order, the median is the $4$th value, which is $41$. The value $42$ is the mean ($\\frac{22 + 29 + 34 + 41 + 48 + 53 + 67}{7} = \\frac{294}{7} = 42$), which is not the same as the median. The value $37.5$ results from incorrectly averaging the $3$rd and $4$th values ($\\frac{34 + 41}{2} = 37.5$), a procedure used for even-sized datasets but not needed here. The value $44.5$ is the midrange ($\\frac{22 + 67}{2} = 44.5$), which is a different measure of center.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I5SM6B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In right triangle $DEF$ with the right angle at $E$, $\\tan(D) = \\frac{7}{4}$. What is the value of $\\sin(D) + \\cos(F)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7\\sqrt{65}}{65}$"},{"key":"B","text":"$\\frac{14\\sqrt{65}}{65}$"},{"key":"C","text":"$\\frac{11}{4}$"},{"key":"D","text":"$\\frac{7}{4}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $\\tan(D) = \\frac{7}{4}$, the side opposite $D$ is $7$ and the side adjacent to $D$ is $4$ (or proportional), giving hypotenuse $\\sqrt{49 + 16} = \\sqrt{65}$. Thus $\\sin(D) = \\frac{7}{\\sqrt{65}}$. Because $D + F = 90°$, the angles are complementary, so $\\cos(F) = \\cos(90° - D) = \\sin(D) = \\frac{7}{\\sqrt{65}}$. Therefore $\\sin(D) + \\cos(F) = \\frac{14}{\\sqrt{65}} = \\frac{14\\sqrt{65}}{65}$. The value $\\frac{7\\sqrt{65}}{65}$ accounts for only $\\sin(D)$ and neglects the $\\cos(F)$ term. The value $\\frac{11}{4}$ results from incorrectly adding $\\frac{7}{4} + 1$. The value $\\frac{7}{4}$ simply restates $\\tan(D)$ without computing the required expression.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IEYT1Q', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which expression is equivalent to $\\frac{9x^2 - 49}{3x^2 + 13x + 14}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3x - 7}{x + 2}$"},{"key":"B","text":"$\\frac{3x + 7}{x + 2}$"},{"key":"C","text":"$\\frac{3x - 7}{x - 2}$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The numerator is a difference of squares: $9x^2 - 49 = (3x - 7)(3x + 7)$. The denominator factors as $3x^2 + 13x + 14 = (3x + 7)(x + 2)$, since $3x \\cdot x = 3x^2$, $3x \\cdot 2 + 7 \\cdot x = 6x + 7x = 13x$, and $7 \\cdot 2 = 14$. Canceling the common factor $(3x + 7)$ yields $\\frac{3x - 7}{x + 2}$. The distractor $\\frac{3x + 7}{x + 2}$ results from canceling the wrong factor from the numerator. The distractor $\\frac{3x - 7}{x - 2}$ has a sign error in the denominator factorization. The distractor $3$ results from dividing only the leading coefficients ($\\frac{9x^2}{3x^2} = 3$) while ignoring the remaining terms.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JG3NKA', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store marks up its wholesale prices by $40\\%$ and then offers a seasonal sale of $25\\%$ off the marked-up price. If the wholesale cost of a jacket is $85$ dollars, what is the sale price, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '89.25', ARRAY['357/4', '89.25'], E'The marked-up price is $85 \\times 1.40 = 119$ dollars. The sale price is $119 \\times 0.75 = 89.25$ dollars. A common error is treating the net effect as $40\\% - 25\\% = 15\\%$, which gives $85 \\times 1.15 = 97.75$ dollars. However, the $25\\%$ discount applies to the already-marked-up price, not the wholesale cost, so the two percentages cannot be combined by simple subtraction.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KO8W14', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What are all values of $x$ that satisfy the inequality $4x + 9 \\leq 37$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq 7$"},{"key":"B","text":"$x \\geq 7$"},{"key":"C","text":"$x \\leq 28$"},{"key":"D","text":"$x \\geq 28$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting $9$ from both sides gives $4x \\leq 28$. Dividing both sides by $4$ gives $x \\leq 7$. The value $x \\geq 7$ reverses the inequality direction, a sign error. The value $x \\leq 28$ results from subtracting $9$ but forgetting to divide by $4$. The value $x \\geq 28$ combines both errors.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L1PAQT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A bookstore offers a membership card for $13$ dollars. Members receive a discount of $8\\%$ on every purchase. If Kayla buys a book priced at $47$ dollars with her membership discount, how much does she pay for the book?', NULL, $lyceon_json$[{"key":"A","text":"$3.76$ dollars"},{"key":"B","text":"$30.24$ dollars"},{"key":"C","text":"$43.24$ dollars"},{"key":"D","text":"$50.76$ dollars"}]$lyceon_json$::jsonb, 'C', NULL, E'The discount is $47 \\times 0.08 = 3.76$ dollars, so the price after discount is $47 - 3.76 = 43.24$ dollars. The membership fee is a one-time cost and is not subtracted from the book price. The value $3.76$ is just the discount amount, not what Kayla pays. The value $30.24$ incorrectly subtracts both the discount and the membership fee ($47 - 3.76 - 13 = 30.24$). The value $50.76$ adds the discount instead of subtracting it ($47 + 3.76 = 50.76$).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MSLL1U', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A taxi company charges a flat fee plus a constant rate per mile. A $13$-mile ride costs $29.70$ dollars, and a $21$-mile ride costs $45.30$ dollars. What is the flat fee, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4.35', ARRAY['87/20', '4.35'], E'Let $f$ represent the flat fee and $r$ represent the rate per mile. The two rides give the equations $f + 13r = 29.70$ and $f + 21r = 45.30$. Subtracting the first equation from the second: $8r = 15.60$, so $r = 1.95$. Substituting back into the first equation: $f + 13(1.95) = 29.70$, which gives $f + 25.35 = 29.70$, so $f = 4.35$. The flat fee is $4.35$ dollars.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N6105H', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'Which of the following ordered pairs $(x, y)$ satisfies the equation $5x + 3y = 41$?', NULL, $lyceon_json$[{"key":"A","text":"$(2, 9)$"},{"key":"B","text":"$(4, 7)$"},{"key":"C","text":"$(5, 6)$"},{"key":"D","text":"$(7, 3)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 4$ and $y = 7$: $5(4) + 3(7) = 20 + 21 = 41$, which matches the right side. For $(2, 9)$: $5(2) + 3(9) = 10 + 27 = 37 \\neq 41$. For $(5, 6)$: $5(5) + 3(6) = 25 + 18 = 43 \\neq 41$. For $(7, 3)$: $5(7) + 3(3) = 35 + 9 = 44 \\neq 41$. Only $(4, 7)$ produces the required sum of $41$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OCH7TP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A school district found that students who eat breakfast before school score an average of $13$ points higher on standardized tests than students who skip breakfast. This finding was based on voluntary survey responses from $1{,}200$ students. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Eating breakfast causes higher test scores."},{"key":"B","text":"There is an association between eating breakfast and higher test scores, but a causal relationship cannot be established."},{"key":"C","text":"Students who skip breakfast should be required to eat breakfast to improve their scores."},{"key":"D","text":"The survey is invalid because the sample size is too small."}]$lyceon_json$::jsonb, 'B', NULL, E'Because the data come from a voluntary survey rather than a randomized experiment, confounding variables (such as socioeconomic status, sleep habits, or parental involvement) may explain the difference. Therefore, only an association can be established, not a causal relationship. Claiming that breakfast causes higher scores overstates what an observational study can conclude. Recommending a policy change based on a correlational finding is not justified. A sample of $1{,}200$ students is not too small; the limitation is the study design, not the sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OFEC47', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $250$ voters in a city found that $58\\%$ support a new park proposal, with a margin of error of $4\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $58\\%$ of all voters in the city support the proposal."},{"key":"B","text":"Between $54\\%$ and $62\\%$ of the sampled voters support the proposal."},{"key":"C","text":"It is plausible that between $54\\%$ and $62\\%$ of all voters in the city support the proposal."},{"key":"D","text":"At most $62\\%$ of all voters in the city support the proposal."}]$lyceon_json$::jsonb, 'C', NULL, E'A sample statistic with a margin of error gives a confidence interval for the population parameter: $58\\% \\pm 4\\%$, or $54\\%$ to $62\\%$. This interval applies to all voters in the city, not just the sample. Stating exactly $58\\%$ ignores sampling variability. Applying the interval only to the sampled voters misidentifies the target of inference. Stating at most $62\\%$ omits the lower bound and mischaracterizes the interval as a one-sided bound.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OVX422', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 - 17x + 72 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 8$ and $x = 9$"},{"key":"B","text":"$x = -8$ and $x = -9$"},{"key":"C","text":"$x = 6$ and $x = 12$"},{"key":"D","text":"$x = 4$ and $x = 18$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring the quadratic gives $(x - 8)(x - 9) = 0$, so $x = 8$ or $x = 9$. The values $x = -8$ and $x = -9$ result from a sign error when setting each factor equal to zero. The values $x = 6$ and $x = 12$ multiply to $72$ but sum to $18$, not $17$. The values $x = 4$ and $x = 18$ also multiply to $72$ but sum to $22$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q2UWKU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A textile factory uses $17$ yards of thread to embroider $4$ placemats. At this rate, how many yards of thread are needed to embroider $28$ placemats?', NULL, $lyceon_json$[{"key":"A","text":"$112$"},{"key":"B","text":"$119$"},{"key":"C","text":"$126$"},{"key":"D","text":"$476$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{17}{4}$ yards per placemat. For $28$ placemats: $\\frac{28}{4} = 7$ batches, and $7 \\times 17 = 119$ yards. The value $112$ results from multiplying $28 \\times 4 = 112$, inverting the ratio. The value $126$ results from computing $\\frac{17}{4}$ as $4.5$ instead of $4.25$, then $28 \\times 4.5 = 126$. The value $476$ results from multiplying $17 \\times 28 = 476$ without dividing by $4$, omitting the per-batch step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R917HI', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A linear function $f$ has $f(0) = 11$ and $f(1) = 17$. What is the value of $f(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$29$"},{"key":"C","text":"$33$"},{"key":"D","text":"$35$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\dfrac{17 - 11}{1 - 0} = 6$, and the $y$-intercept is $11$, so $f(x) = 6x + 11$. Therefore $f(3) = 6(3) + 11 = 18 + 11 = 29$. The value $23$ equals $f(2) = 12 + 11$, resulting from evaluating at the wrong input. The value $33$ equals $11 \\times 3$, which incorrectly multiplies the $y$-intercept by $3$ instead of using the linear function. The value $35$ results from using an incorrect slope of $8$: $8(3) + 11 = 35$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S201HK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $37°$ and the measure of angle $Q$ is $58°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$75$"},{"key":"B","text":"$85$"},{"key":"C","text":"$95$"},{"key":"D","text":"$105$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of the interior angles of a triangle is $180°$. Therefore, angle $R = 180° - 37° - 58° = 85°$. The value $75°$ results from a subtraction error. The value $95°$ could arise from incorrectly believing the sum exceeds $180°$ or from an exterior-angle confusion. The value $105°$ results from miscomputing $180 - 37 - 58$ as $180 - 75$ instead of $180 - 95$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ST3CXU', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(2x - 7)(3x + 11)$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^2 + 43x - 77$"},{"key":"B","text":"$6x^2 + x - 77$"},{"key":"C","text":"$6x^2 + x + 77$"},{"key":"D","text":"$5x^2 + x - 77$"}]$lyceon_json$::jsonb, 'B', NULL, E'Applying FOIL: $(2x)(3x) = 6x^2$, $(2x)(11) = 22x$, $(-7)(3x) = -21x$, $(-7)(11) = -77$. Combining: $6x^2 + 22x - 21x - 77 = 6x^2 + x - 77$. The distractor $6x^2 + 43x - 77$ results from adding the magnitudes of the middle terms ($22 + 21 = 43$) instead of subtracting. The distractor $6x^2 + x + 77$ has the correct middle term but incorrectly makes the constant positive. The distractor $5x^2 + x - 77$ has an arithmetic slip on the leading term ($2 \\times 3 = 5$ instead of $6$).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SY8BS1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A chemist mixes a solution using $7$ milliliters of reagent for every $11$ milliliters of solvent. If the chemist wants to prepare $414$ milliliters of the solution in total, how many milliliters of reagent are needed?', NULL, $lyceon_json$[{"key":"A","text":"$161$"},{"key":"B","text":"$207$"},{"key":"C","text":"$253$"},{"key":"D","text":"$322$"}]$lyceon_json$::jsonb, 'A', NULL, E'The ratio of reagent to solvent is $7:11$, so the total parts are $7 + 11 = 18$. The reagent fraction is $\\frac{7}{18}$. Reagent needed: $414 \\times \\frac{7}{18} = \\frac{414}{18} \\times 7 = 23 \\times 7 = 161$ milliliters. The value $207$ results from dividing $414$ by $2$, splitting evenly between two components and ignoring the unequal ratio. The value $253$ is the solvent amount ($414 \\times \\frac{11}{18} = 253$), answering the wrong component. The value $322$ results from computing $414 \\times \\frac{7}{9}$, using only the reagent ratio part ($9$ instead of the sum $18$) as the denominator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T036OH', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle in the $xy$-plane has the equation $x^2 + y^2 - 18x + 8y + 57 = 0$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{10}$"},{"key":"B","text":"$2\\sqrt{10}$"},{"key":"C","text":"$40$"},{"key":"D","text":"$4\\sqrt{10}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: $(x^2 - 18x + 81) + (y^2 + 8y + 16) + 57 - 81 - 16 = 0$, which simplifies to $(x - 9)^2 + (y + 4)^2 = 40$. The radius is $\\sqrt{40} = 2\\sqrt{10}$. The value $\\sqrt{10}$ results from an error in computing the constant, such as subtracting only one completing-the-square term. The value $40$ gives $r^2$ instead of $r$. The value $4\\sqrt{10}$ results from an arithmetic error when simplifying the radical.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T2LIVQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = (x - 3)^2 + 7$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$7$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function is in vertex form $f(x) = (x - h)^2 + k$ with vertex at $(3, 7)$. Since the coefficient of the squared term is positive, the parabola opens upward and the minimum value is $7$. The distractor $3$ confuses the $x$-coordinate of the vertex with the minimum value. The distractor $-3$ makes a sign error on the $x$-coordinate and also confuses it with the minimum. The distractor $16$ results from evaluating $f(0) = 9 + 7 = 16$ rather than identifying the vertex.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TBDKYW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A factory produces widgets on two assembly lines. Line $P$ produces $57\\%$ of all widgets and Line $Q$ produces the rest. The defect rate for Line $P$ is $3\\%$ and the defect rate for Line $Q$ is $8\\%$. If a widget chosen at random is found to be defective, what is the probability that it was produced by Line $Q$, rounded to the nearest hundredth?', NULL, $lyceon_json$[{"key":"A","text":"$0.43$"},{"key":"B","text":"$0.67$"},{"key":"C","text":"$0.08$"},{"key":"D","text":"$0.33$"}]$lyceon_json$::jsonb, 'B', NULL, E'Line $Q$ produces $43\\%$ of widgets. The total probability of a defect is $P(D) = (0.57)(0.03) + (0.43)(0.08) = 0.0171 + 0.0344 = 0.0515$. By Bayes'' theorem, $P(Q \\mid D) = \\frac{(0.43)(0.08)}{0.0515} = \\frac{0.0344}{0.0515} \\approx 0.67$. Selecting $0.43$ confuses the prior probability of Line $Q$ with the posterior probability after observing a defect. Selecting $0.08$ confuses the defect rate of Line $Q$ with the conditional probability that a defective widget came from Line $Q$. Selecting $0.33$ results from computing $P(P \\mid D)$ instead, or from an arithmetic error in the division.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U4JKDD', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tested a new headache medication. They recruited $500$ volunteers with chronic headaches and randomly assigned $250$ to receive the medication and $250$ to receive a placebo. Neither the participants nor the researchers administering the treatment knew which group each participant was in. After $6$ weeks, $67\\%$ of the medication group reported fewer headaches, compared to $41\\%$ of the placebo group. A journalist reported: "The medication reduced headaches in $67\\%$ of all headache sufferers." Which of the following best identifies the flaw in the journalist''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The study did not use random assignment, so no causal claim can be made."},{"key":"B","text":"The placebo group also showed improvement, so the medication had no effect."},{"key":"C","text":"The claim generalizes a percentage from the treatment group to all headache sufferers without accounting for the placebo effect or the study's specific population."},{"key":"D","text":"The study is invalid because the participants were volunteers rather than a random sample from the population."}]$lyceon_json$::jsonb, 'C', NULL, E'The journalist''s claim takes the $67\\%$ figure from the treatment group and applies it to all headache sufferers without subtracting the placebo effect ($41\\%$ improved without medication) and without noting that the study volunteers may not represent all headache sufferers. The study did use random assignment, so that is not the flaw. While the placebo group improved, the medication group improved at a substantially higher rate ($67\\%$ vs. $41\\%$), so it is incorrect to say the medication had no effect. The use of volunteers does limit generalizability, but calling the study entirely invalid overstates this concern; the core flaw in the journalist''s claim is the uncritical generalization of the raw treatment-group percentage.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UJLDAR', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'What is the value of $x$ if $\\dfrac{5(x + 3)}{2} = 3x + 11$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-7', ARRAY['-7'], E'Multiply both sides by $2$: $5(x + 3) = 6x + 22$. Distribute: $5x + 15 = 6x + 22$. Subtract $5x$ from both sides: $15 = x + 22$. Subtract $22$: $x = -7$. Verification: the left side is $\\dfrac{5(-7 + 3)}{2} = \\dfrac{5(-4)}{2} = \\dfrac{-20}{2} = -10$. The right side is $3(-7) + 11 = -21 + 11 = -10$. Both sides equal $-10$, confirming $x = -7$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VN02F6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $PQR$, $PQ = 15$, $QR = 21$, and $PR = 27$. Point $S$ lies on $\\overline{QR}$ such that $\\overline{PS}$ bisects angle $QPR$. What is the length of $QS$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{15}{2}$"},{"key":"B","text":"$9$"},{"key":"C","text":"$\\frac{21}{2}$"},{"key":"D","text":"$\\frac{27}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the angle bisector theorem, the bisector from $P$ divides the opposite side $QR$ in the ratio $\\frac{QS}{SR} = \\frac{PQ}{PR} = \\frac{15}{27} = \\frac{5}{9}$. Since $QS + SR = 21$, we have $QS = \\frac{5}{14} \\cdot 21 = \\frac{15}{2}$. The value $9$ results from setting up the ratio incorrectly as $\\frac{PQ}{QR}$. The value $\\frac{21}{2}$ assumes the bisector divides the opposite side into two equal parts, confusing the angle bisector with a median. The value $\\frac{27}{2}$ arises from reversing the ratio to $\\frac{PR}{PQ} = \\frac{9}{5}$ and applying it incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y0OYQ8', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'If $x + y = 13$ and $x^2 + y^2 = 89$, what is the value of $xy$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '40', ARRAY['40'], E'Squaring the first equation gives $(x + y)^2 = x^2 + 2xy + y^2 = 169$. Substituting $x^2 + y^2 = 89$ yields $89 + 2xy = 169$, so $2xy = 80$ and $xy = 40$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y2M0GL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $JKL$, the exterior angle at vertex $L$ measures $139°$. If angle $J$ measures $67°$, what is the measure, in degrees, of angle $K$?', NULL, $lyceon_json$[{"key":"A","text":"$41$"},{"key":"B","text":"$67$"},{"key":"C","text":"$72$"},{"key":"D","text":"$108$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Thus $139° = 67° + \\text{angle } K$, which gives angle $K = 72°$. The value $41°$ is the interior angle at $L$ (computed as $180° - 139°$) and does not answer the question. The value $67°$ incorrectly assumes angle $K$ equals angle $J$. The value $108°$ results from subtracting $72°$ from $180°$, confusing the supplement with the angle itself.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YDWP3K', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'Given the system of equations $3x + 2y = 19$ and $x - 2y = -7$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'Adding the two equations eliminates $y$: $(3x + 2y) + (x - 2y) = 19 + (-7)$, which simplifies to $4x = 12$. Dividing both sides by $4$ gives $x = 3$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YQH4MM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'Researchers wanted to determine whether a new fertilizer increases tomato yield. They randomly assigned $46$ tomato plants to receive the new fertilizer and $46$ plants to receive the standard fertilizer, then measured the yield after $8$ weeks. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"An observational study"},{"key":"B","text":"A randomized experiment"},{"key":"C","text":"A survey"},{"key":"D","text":"A case study"}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researchers randomly assigned plants to treatment groups (new fertilizer versus standard fertilizer), this is a randomized experiment. An observational study would observe plants without assigning treatments. A survey collects self-reported data from respondents, which is not applicable to plants. A case study examines a single subject or a small group in depth, not a controlled comparison between groups.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z3JDFT', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of $k$ does the system of equations $5x - 3y = 11$ and $kx - 9y = 7$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$15$"},{"key":"D","text":"$45$"}]$lyceon_json$::jsonb, 'C', NULL, E'A system of two linear equations has no solution when the lines are parallel but not coincident. Writing both equations in the form $ax + by = c$, the lines are parallel when $\\frac{5}{k} = \\frac{-3}{-9} = \\frac{1}{3}$. Cross-multiplying gives $k = 15$. Checking that the lines are not coincident: $\\frac{11}{7} \\neq \\frac{1}{3}$, so the system indeed has no solution when $k = 15$. The value $3$ comes from computing $\\frac{-9}{-3}$ instead of setting the correct ratio of $x$-coefficients to $y$-coefficients. The value $5$ incorrectly reuses the coefficient from the first equation without forming the proportionality condition. The value $45$ results from multiplying $5 \\times 9$ rather than solving the ratio $\\frac{5}{k} = \\frac{1}{3}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZJWISC', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In a $30°$-$60°$-$90°$ triangle, the side opposite the $60°$ angle has length $17\\sqrt{3}$. What is the length of the hypotenuse?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '34', ARRAY['34'], E'In a $30°$-$60°$-$90°$ triangle, the sides are in the ratio $x : x\\sqrt{3} : 2x$. The side opposite $60°$ is $x\\sqrt{3}$. Setting $x\\sqrt{3} = 17\\sqrt{3}$ gives $x = 17$. The hypotenuse is $2x = 2(17) = 34$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZSY55K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The population of a town was $8{,}500$ in 2017 and $10{,}285$ in 2022. What is the percent increase in the town''s population from 2017 to 2022?', NULL, $lyceon_json$[{"key":"A","text":"$17.4\\%$"},{"key":"B","text":"$21\\%$"},{"key":"C","text":"$121\\%$"},{"key":"D","text":"$210\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The increase is $10{,}285 - 8{,}500 = 1{,}785$. The percent increase is $\\frac{1{,}785}{8{,}500} \\times 100 = 21\\%$. The value $17.4\\%$ results from dividing by the new population instead of the original ($\\frac{1{,}785}{10{,}285} \\approx 17.4\\%$). The value $121\\%$ comes from computing $\\frac{10{,}285}{8{,}500} \\times 100 = 121\\%$, reporting the total ratio rather than subtracting $100\\%$ for the change. The value $210\\%$ results from a decimal-place error in the denominator, computing $\\frac{1{,}785}{850} \\times 100 = 210\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23ED2Z4', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Honeybees communicate the location of food sources through a behavior known as the waggle dance. A forager bee returning to the hive performs a figure-eight pattern, vibrating its body along the central axis. The angle of this axis relative to the vertical indicates the direction of the food source in relation to the sun, while the duration of the waggle phase corresponds to distance. Other bees observing the dance can then navigate to the food with remarkable precision.', $lyceon_json$[{"key":"A","text":"It explains the mechanism by which the waggle dance conveys specific information."},{"key":"B","text":"It challenges a common misconception about bee navigation."},{"key":"C","text":"It presents a hypothesis that the passage goes on to test."},{"key":"D","text":"It describes the evolutionary origin of the waggle dance."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence details how the angle and duration of the waggle encode direction and distance, thereby explaining the specific informational mechanism of the dance. No misconception is introduced or challenged anywhere in the passage, making the claim about challenging a misconception unsupported. The passage does not frame any statement as a hypothesis requiring testing; it presents established knowledge. The passage never discusses evolutionary history, so the claim about evolutionary origin has no textual basis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23HDFND', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the central claim of the text?', E'Neurolinguist Priya Chakravarti has argued that the widely cited "bilingual advantage" in executive function tasks may be an artifact of publication bias rather than a genuine cognitive phenomenon. Reviewing 137 studies conducted between 2004 and 2022, Chakravarti found that experiments reporting a bilingual advantage were cited, on average, 4.7 times more frequently than those reporting null results, creating an inflated impression of consensus. She does not deny that managing two linguistic systems engages executive control networks; rather, she contends that the leap from neural engagement to measurable behavioral superiority on laboratory tasks has not been reliably demonstrated. Her position occupies a middle ground: bilingualism shapes certain neural pathways without necessarily conferring a detectable performance edge in controlled settings.', $lyceon_json$[{"key":"A","text":"Chakravarti argues that while bilingualism engages executive control networks, the evidence that this engagement translates into measurable behavioral advantages on laboratory tasks is unreliable, partly due to publication bias."},{"key":"B","text":"Chakravarti rejects the notion that bilingualism has any effect on the brain's executive control systems, attributing the bilingual advantage entirely to flawed research methods."},{"key":"C","text":"Chakravarti's primary concern is that researchers studying bilingualism have used inconsistent definitions of executive function across the 137 studies she reviewed."},{"key":"D","text":"Chakravarti maintains that the bilingual advantage is real but too small to be detected by current laboratory instruments, suggesting more sensitive measures are needed."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Chakravarti''s nuanced position: she acknowledges that managing two languages engages executive control networks but contends that the leap from neural engagement to measurable behavioral superiority has not been reliably demonstrated, with publication bias inflating the appearance of consensus. The correct answer captures both her acknowledgment of neural engagement and her skepticism about behavioral evidence. The claim that she rejects any effect on executive control contradicts the passage, which explicitly states she does not deny neural engagement. The suggestion that her primary concern is inconsistent definitions of executive function is fabricated; the passage identifies publication bias and citation frequency as her methodological critique, not definitional inconsistency. The characterization that she believes the advantage is real but too small to detect misrepresents her stance: she questions whether a behavioral advantage exists at all, rather than arguing it exists below a detection threshold.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23QJ7CR', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Urban planners have increasingly advocated for mixed-use zoning as a solution to suburban sprawl. By integrating residential, commercial, and recreational spaces within walkable districts, mixed-use developments reduce automobile dependence and foster vibrant community life.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25N1D5Y', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a policy brief about soil salinity for an audience of agricultural officials unfamiliar with the science. The student wants to explain the mechanism by which salinity damages crops while conveying the economic urgency of the problem. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26KTXXL', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from a research study, if accurate, would most effectively support Okamura''s position over Lindgren''s?', E'Behavioral economist Yuki Okamura has challenged the standard interpretation of loss aversion, which holds that people weigh potential losses roughly twice as heavily as equivalent gains. Okamura argues that this asymmetry diminishes substantially when decision-makers have prior experience with the specific domain of choice: seasoned stock traders, for instance, show loss-gain sensitivity ratios closer to 1:1 than the canonical 2:1. Cognitive psychologist Erik Lindgren counters that Okamura''s findings reflect selection bias — individuals who remain active traders may simply be those who were never strongly loss-averse to begin with, and that the underlying cognitive asymmetry persists in the general population regardless of experience.', $lyceon_json$[{"key":"A","text":"\"Participants who were randomly assigned to complete 40 simulated investment rounds before the critical trial exhibited loss-gain ratios of 1.15:1, compared with 1.97:1 for participants who received no prior simulation exposure.\""},{"key":"B","text":"\"Among professional traders surveyed, 83 percent reported that they had entered the financial industry because they felt comfortable with risk, suggesting a pre-existing dispositional tolerance for losses.\""},{"key":"C","text":"\"Loss aversion ratios measured in laboratory settings remain stable across repeated measurements within a single experimental session, with test-retest reliability exceeding 0.91.\""},{"key":"D","text":"\"Cross-cultural studies confirm that loss aversion at a 2:1 ratio is observed in populations across 47 countries, regardless of economic development or market participation rates.\""}]$lyceon_json$::jsonb, 'A', NULL, E'Okamura claims that experience in a domain reduces loss aversion. Lindgren counters that Okamura''s data reflects selection bias: people who remain active traders may have been low in loss aversion from the start. The quotation about randomly assigned participants who completed simulated investment rounds before the critical trial addresses Lindgren''s objection directly: random assignment eliminates selection bias, and the reduction in loss-gain ratios from 1.97:1 to 1.15:1 after simulated experience supports Okamura''s claim that experience itself drives the reduction. The survey finding that most professional traders entered finance because they felt comfortable with risk actually supports Lindgren''s selection-bias critique rather than Okamura''s experience-based argument. The finding about stable loss aversion ratios within a single session addresses test reliability, not whether experience changes loss aversion over time. The cross-cultural confirmation of 2:1 loss aversion would support the standard interpretation that Okamura challenges, not Okamura''s position.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26O97PL', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Volcanic glass, known as obsidian, was one of the earliest materials used for cutting tools in prehistoric Mesoamerica. Obsidian''s conchoidal fracture pattern produces edges that can be thinner than modern surgical steel _______ archaeologists have recovered obsidian blades from sites in the Tehuacan Valley dating to approximately 10,000 BCE.', $lyceon_json$[{"key":"A","text":"scalpels, archaeologists"},{"key":"B","text":"scalpels. Archaeologists"},{"key":"C","text":"scalpels archaeologists"},{"key":"D","text":"scalpels; and archaeologists"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage contains two independent clauses: one about obsidian''s fracture pattern producing thin edges and another about archaeologists recovering blades. A period correctly separates two independent clauses. Joining them with only a comma creates a comma splice. Omitting all punctuation produces a run-on sentence. Using a semicolon followed by a coordinating conjunction is non-standard punctuation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27WS5ST', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After surveying 1,400 tide pools along the Oregon coast over a period of nineteen months, marine biologist Priya Chandrasekaran identified an unexpected _______ species diversity was highest not in the largest pools, as previous models had predicted, but in mid-sized pools measuring between 0.4 and 1.1 square meters.', $lyceon_json$[{"key":"A","text":"pattern, species"},{"key":"B","text":"pattern; and species"},{"key":"C","text":"pattern: species"},{"key":"D","text":"pattern species"}]$lyceon_json$::jsonb, 'C', NULL, E'The second clause specifies the content of the "unexpected pattern" mentioned in the first clause. A colon is the correct punctuation when the second independent clause explains or elaborates on what precedes it. A comma between the two independent clauses creates a comma splice. A semicolon followed by a coordinating conjunction is non-standard. Omitting punctuation entirely produces a fused sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2876TJ1', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "volatile" most nearly mean?', E'Researchers studying the atmospheric composition of Venus have long noted the planet''s volatile chemical environment. Sulfuric acid clouds blanket the surface, temperatures exceed 460 degrees Celsius, and atmospheric pressure is roughly ninety times that of Earth. These unstable and rapidly shifting conditions make sustained robotic exploration extraordinarily difficult.', $lyceon_json$[{"key":"A","text":"unstable"},{"key":"B","text":"angry"},{"key":"C","text":"flammable"},{"key":"D","text":"rare"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes conditions on Venus that are "rapidly shifting" and difficult to predict, directly supporting the meaning of unstable. The word "angry" relates to human emotion and has no connection to chemical or atmospheric conditions. "Flammable" refers to the capacity to catch fire, which is unrelated to the passage''s description of pressure and temperature variability. "Rare" means uncommon, but the passage emphasizes changeability, not scarcity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW289GJGB', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "tempered" most nearly mean?', E'The glassblower Marguerite Kolev earned recognition not for flamboyant designs but for her tempered approach to ornamentation. Where contemporaries layered color upon color, Kolev exercised deliberate restraint, applying a single accent hue only where it served the vessel''s structural line. Critics noted that this measured sensibility gave her pieces an architectural clarity absent from the more effusive work of her peers.', $lyceon_json$[{"key":"A","text":"restrained"},{"key":"B","text":"heated"},{"key":"C","text":"furious"},{"key":"D","text":"provisional"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts Kolev''s "deliberate restraint" and "measured sensibility" with the "effusive" and layered approach of her contemporaries, establishing that her approach was controlled and moderate — that is, restrained. "Heated" relates to the metallurgical or glassmaking sense of tempering through heat treatment, but the passage is describing an aesthetic philosophy, not a physical process. "Furious" means intensely angry, which contradicts the passage''s emphasis on calm deliberation. "Provisional" means temporary or tentative, but Kolev''s approach is presented as a consistent artistic identity, not something adopted on a trial basis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DL1KI4', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The Atacama Desert in Chile receives less than one millimeter of rainfall per year, making it one of the driest places on Earth. _______ its extreme aridity, the Atacama supports colonies of specialized microorganisms that thrive in salt flats and mineral-rich soils.', $lyceon_json$[{"key":"A","text":"Despite"},{"key":"B","text":"Because of"},{"key":"C","text":"In addition to"},{"key":"D","text":"Prior to"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that the Atacama is extremely dry, then states that microorganisms nonetheless thrive there. This contrast requires a concessive transition. "Despite" correctly signals that the second fact is surprising given the first. "Because of" reverses the logic by implying aridity causes the organisms to thrive, which misrepresents the relationship. "In addition to" suggests the second sentence merely adds to the first without acknowledging the contrast. "Prior to" introduces an illogical temporal relationship between aridity and microbial life.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E4WFWT', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While the ceramic fragments recovered from the Jōmon-period excavation near Hakodate exhibit the cord-marked patterns characteristic of vessels produced between 3,000 and 2,000 BCE, the unusually high concentration of arsenic in the clay, which geochemist Yuki Tanabe attributes to a now-depleted mineral deposit in the adjacent _______ that the vessels were manufactured locally rather than imported through the trade networks connecting coastal settlements during that era.', $lyceon_json$[{"key":"A","text":"hillside, suggests"},{"key":"B","text":"hillside. Suggests"},{"key":"C","text":"hillside; suggests"},{"key":"D","text":"hillside suggests"}]$lyceon_json$::jsonb, 'A', NULL, E'The main clause subject is "the unusually high concentration of arsenic in the clay," and its verb is "suggests." The nonrestrictive "which" clause, which was opened with a comma before "which," must be closed with a matching comma before the main verb continues. A period before "suggests" would create a sentence fragment lacking a subject. A semicolon would incorrectly split the main clause''s subject from its predicate. Omitting the closing comma leaves the nonrestrictive clause improperly punctuated, since the opening comma before "which" signals nonrestrictive status and requires a closing comma to complete the pair.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E87GC1', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "precipitated" most nearly mean?', E'The 1847 financial crisis in Britain precipitated a wave of emigration from Scottish highland communities. Families who had endured decades of land consolidation and rising rents found themselves unable to sustain even subsistence farming. The collapse of commodity prices that autumn removed whatever slim economic margin remained, and within months, thousands had booked passage to Nova Scotia and Upper Canada.', $lyceon_json$[{"key":"A","text":"triggered"},{"key":"B","text":"condensed"},{"key":"C","text":"predicted"},{"key":"D","text":"dissolved"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a financial crisis that directly caused a wave of emigration, so "triggered" captures the meaning of setting something in motion. "Condensed" refers to compressing or making denser, a chemistry-related sense of "precipitate" that does not fit the causal relationship described. "Predicted" means to forecast in advance, but the passage presents the crisis as a cause, not a forecast. "Dissolved" means to break apart or disintegrate, which is the opposite of initiating an event.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EY30OX', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the city council approved the rezoning proposal in March 2023, opponents of the measure argued that increased commercial development _______ residential property values in the surrounding neighborhoods, a concern that several independent appraisers later confirmed was well-founded.', $lyceon_json$[{"key":"A","text":"would diminish"},{"key":"B","text":"will diminish"},{"key":"C","text":"diminishes"},{"key":"D","text":"had diminished"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence reports what opponents "argued" (past tense) about a future consequence. In indirect discourse governed by a past-tense reporting verb, a future prediction requires the conditional "would," not the present-tense "will." The simple present "diminishes" is inconsistent with the past-tense framing and implies a habitual or current action. The past perfect "had diminished" incorrectly suggests the decline had already occurred before the opponents made their argument, contradicting the predictive nature of their claim.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F4AEDI', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Historians have traditionally attributed the decline of the Western Roman Empire to military pressures from Germanic tribes. According to this view, repeated invasions overwhelmed Rome''s defensive capacity, culminating in the deposition of Romulus Augustulus in 476 CE.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H1YZQP', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best describes a central tension between the two texts?', E'Text 1: Cognitive scientist Elara Phelan argues that large language models exhibit a form of understanding that, while distinct from human cognition, is functionally analogous to it. When a model generates coherent responses to novel prompts it has never encountered in training, Phelan contends, it demonstrates an ability to generalize that satisfies pragmatic criteria for comprehension. She maintains that insisting on phenomenal consciousness as a prerequisite for understanding imposes an unnecessarily restrictive standard.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H30BMQ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Myrmecologists have long observed that leafcutter ants cultivate fungal gardens by feeding them freshly cut vegetation. Recent genomic analyses reveal that these fungi have co-evolved with the ants over millions of years, losing the ability to survive independently. _______ the relationship is not merely beneficial but obligatory: neither organism can persist without the other.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The final sentence restates the preceding information in more precise terms, clarifying that the co-evolutionary dependency amounts to an obligatory relationship. "In other words" correctly signals this restatement. "By contrast" implies the final sentence opposes the prior claim, but both sentences describe the same mutual dependency. "For instance" would introduce a specific example, yet the final sentence is a generalization, not an illustration. "Meanwhile" suggests simultaneous but unrelated events, which mischaracterizes the logical continuity between the sentences.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I4G5EU', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The restoration team''s responsibilities included cataloging each artifact''s condition, photographing surface details under ultraviolet light, and _______ any residual adhesive from previous conservation attempts using a solvent that the museum''s chief conservator had personally approved for use on seventeenth-century gilded frames.', $lyceon_json$[{"key":"A","text":"they removed"},{"key":"B","text":"removal of"},{"key":"C","text":"removing"},{"key":"D","text":"to remove"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence lists three responsibilities using gerunds: "cataloging," "photographing," and the third item must maintain the same parallel structure. The gerund "removing" correctly matches the gerund forms of the other two items in the series. Inserting "they removed" breaks the parallel gerund structure and introduces a clause where a noun phrase is required. The noun form "removal of" disrupts the gerund parallelism with a nominalization. The infinitive "to remove" similarly breaks the established gerund pattern.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I77L6U', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Astronomers studying the exoplanet WASP-39b have hypothesized that its atmosphere contains significant concentrations of sulfur dioxide, a compound that on Earth is typically associated with volcanic activity. Using spectroscopic data from the James Webb Space Telescope, the research team identified absorption features at wavelengths consistent with sulfur dioxide. However, the team has acknowledged that photochemical reactions driven by the host star''s ultraviolet radiation could produce similar spectral signatures without any volcanic source.', $lyceon_json$[{"key":"A","text":"Spectral analysis reveals that WASP-39b's atmosphere also contains silicate particles commonly ejected during volcanic eruptions."},{"key":"B","text":"The host star of WASP-39b emits ultraviolet radiation at intensities far higher than those of the Sun."},{"key":"C","text":"Other exoplanets orbiting stars with low ultraviolet output also show sulfur dioxide absorption features."},{"key":"D","text":"Laboratory simulations demonstrate that sulfur dioxide breaks down rapidly when exposed to intense ultraviolet radiation."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers hypothesize that sulfur dioxide in WASP-39b''s atmosphere originates from volcanic activity. Finding silicate particles, which are characteristic volcanic ejecta, would provide independent corroboration of a volcanic source, directly supporting the hypothesis. High ultraviolet output from the host star would actually strengthen the alternative explanation (photochemical production), undermining rather than supporting the volcanic hypothesis. The presence of sulfur dioxide on planets with low ultraviolet output would suggest that photochemistry is not the only source, but it would not directly link the compound on WASP-39b to volcanism specifically. The rapid breakdown of sulfur dioxide under ultraviolet radiation would complicate interpretation of the spectral data but would not provide positive evidence for a volcanic origin.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JMWNZK', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the archaeologists'' conclusion?', E'Archaeologists excavating a settlement in central Anatolia dated to approximately 7400 BCE uncovered 23 obsidian blades whose chemical composition matched volcanic deposits located 190 kilometers to the northeast, near modern-day Acigöl. The team concluded that the settlement''s inhabitants maintained an organized long-distance trade network, reasoning that transporting fragile obsidian over such terrain would have required planned expeditions with dedicated carriers rather than incidental exchanges between neighboring groups. The archaeologists pointed to the uniformity of the blades'' craftsmanship as further evidence of specialized production at or near the source.', $lyceon_json$[{"key":"A","text":"Obsidian deposits with an identical chemical signature have recently been identified at a site only 11 kilometers from the settlement."},{"key":"B","text":"Other Neolithic settlements in Anatolia also contain obsidian tools sourced from the Acigöl region."},{"key":"C","text":"The blades show microscopic wear patterns indicating they were used for processing animal hides."},{"key":"D","text":"Volcanic glass was considered a valuable prestige material in several contemporaneous Neolithic cultures."}]$lyceon_json$::jsonb, 'A', NULL, E'The archaeologists'' conclusion rests on the 190-kilometer distance between the settlement and the known obsidian source, which they argue necessitated organized long-distance trade. If a chemically identical obsidian deposit existed only 11 kilometers away, the blades could have been obtained locally, eliminating the need for a long-distance trade network and directly undermining the conclusion. The fact that other settlements also obtained Acigöl obsidian does not weaken the claim about this particular settlement''s trade network; it could even reinforce the idea of widespread trade. Evidence that the blades were used for processing hides addresses their function, not their origin or the means by which they were acquired. The observation that volcanic glass was valued as a prestige material in other cultures is tangential to whether this settlement specifically relied on long-distance trade to obtain it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LEU2Y6', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare orchids housed in the university''s botanical greenhouse _______ a dedicated team of three graduate students who monitor temperature, humidity, and soil composition on a daily basis to ensure optimal growing conditions.', $lyceon_json$[{"key":"A","text":"require"},{"key":"B","text":"requires"},{"key":"C","text":"are requiring"},{"key":"D","text":"have required"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is the singular noun "collection," not the plural "orchids" in the intervening prepositional phrase. A singular subject requires a singular verb form. The plural form "require" incorrectly treats "orchids" as the subject. "Are requiring" is plural and uses a progressive aspect inappropriate for a habitual state. "Have required" is plural and shifts to a present perfect tense unsupported by the context.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OVKEF2', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing an article about urban beekeeping for a community newsletter. The student wants to emphasize the environmental benefits of the practice. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P3BVHM', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 2019, landscape architect Mariana Solís proposed retrofitting flat-roofed commercial buildings in Phoenix, Arizona, with modular green roof systems planted with native Sonoran Desert species such as brittlebush and desert marigold. Conventional green roofs rely on sedums and grasses suited to temperate climates, but these plants require supplemental irrigation that is impractical in arid regions where water costs have risen by 37 percent since 2014. Solís''s prototypes, tested on a 940-square-meter warehouse roof, reduced interior surface temperatures by an average of 8.3 degrees Celsius during July while consuming only rainwater captured by integrated cisterns. Her results challenged the assumption that green roofs are viable only in regions with ample precipitation.', $lyceon_json$[{"key":"A","text":"Solís's work demonstrated that green roofs can be adapted for arid climates by using native desert plants and rainwater capture, countering assumptions about their geographic limitations."},{"key":"B","text":"Green roofs have historically failed in desert environments because building owners are unwilling to invest in the specialized infrastructure they require."},{"key":"C","text":"The primary advantage of Solís's green roof design is that it lowers water costs for commercial building operators in Phoenix."},{"key":"D","text":"Solís's research focuses on comparing the thermal insulation properties of sedums with those of Sonoran Desert plant species."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how Solís adapted the green roof concept for arid conditions by substituting native desert species and using rainwater cisterns, achieving significant temperature reduction and challenging the belief that green roofs require ample rainfall. The answer capturing this adaptation and the overturning of geographic assumptions reflects the passage''s central point. The claim that green roofs failed in deserts because of owner unwillingness is not stated anywhere in the text; the passage attributes the problem to impractical irrigation needs, not owner resistance. The suggestion that lowering water costs is the primary advantage misrepresents the passage, which emphasizes thermal performance and viability rather than cost savings. The characterization of the research as a comparison between sedums and desert species distorts the passage: Solís did not conduct a side-by-side comparison but rather proposed a new approach after noting that conventional plants are unsuitable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PRHK6L', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Cognitive scientist Renata Olivos conducted experiments in which participants listened to short musical phrases and then attempted to recall sequences of digits presented immediately afterward. Olivos found that recall accuracy was significantly lower when the musical phrases contained unexpected harmonic shifts — such as an abrupt modulation from a major key to a distant minor key — compared to when the phrases followed conventional harmonic progressions. Olivos interpreted this result as evidence that ________', $lyceon_json$[{"key":"A","text":"processing surprising harmonic information consumes cognitive resources that would otherwise be available for the digit-recall task."},{"key":"B","text":"participants with formal musical training are generally better at recalling digit sequences than those without such training."},{"key":"C","text":"the emotional associations of minor keys interfere with memory encoding more than those of major keys."},{"key":"D","text":"unexpected harmonic shifts cause temporary hearing fatigue that reduces the ability to perceive subsequent auditory stimuli."}]$lyceon_json$::jsonb, 'A', NULL, E'The experiment shows that unexpected harmonic shifts in music impair recall of digits presented afterward. The most logical interpretation is that processing the surprising musical information draws on cognitive resources that are then unavailable for the memory task — a resource-competition explanation consistent with the experimental design. The claim about formally trained musicians performing better on digit recall introduces a variable (musical training) not discussed in the passage. The suggestion that minor keys'' emotional associations specifically interfere with memory misreads the passage: the critical variable is the unexpectedness of the harmonic shift, not the minor key itself, since a conventional minor-key phrase would presumably not produce the same effect. The hearing-fatigue explanation is physiologically implausible for brief musical phrases and is not supported by anything in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SWRQO3', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1903, Orville and Wilbur Wright achieved powered flight at Kitty Hawk, an event widely celebrated as a triumph of American ingenuity. Yet the brothers'' accomplishment did not emerge in isolation. Otto Lilienthal''s glider experiments in Germany during the 1890s provided critical aerodynamic data, and Octave Chanute''s biplane designs influenced the Wrights'' wing-warping approach. Samuel Langley''s failed Aerodrome launch, just nine days before the Wrights'' success, even shaped public expectations of what was possible. Recognizing these antecedents does not diminish the Wrights'' achievement; rather, it situates their breakthrough within a broader international effort.', $lyceon_json$[{"key":"A","text":"It introduces a widely held view, presents evidence that complicates that view, and then offers a reconciling interpretation."},{"key":"B","text":"It describes a scientific controversy, evaluates competing claims, and declares a winner."},{"key":"C","text":"It narrates a sequence of historical events in strict chronological order."},{"key":"D","text":"It proposes a new theory of aviation history and defends it against objections."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage opens with the popular narrative of the Wrights as sole pioneers, then introduces predecessors whose contributions complicate that narrative, and finally reconciles both perspectives by arguing that acknowledging antecedents enriches rather than diminishes the Wrights'' achievement. The passage does not frame the history as a controversy with competing claims or declare any single figure the winner. While historical events are mentioned, they are not presented in strict chronological order — for instance, the passage moves from 1903 back to the 1890s — and chronological narration is not the organizing principle. No new theory is proposed; instead, the passage contextualizes an existing historical event.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T7J90T', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Historian Emilia Vardan argues that the decline of the Khmer Empire was driven primarily by prolonged droughts that undermined its hydraulic infrastructure. Archaeologist Tomoko Nishi, however, points to evidence of extensive military campaigns during the same period, suggesting that resource diversion toward warfare weakened the empire''s capacity to maintain its reservoirs. _______ both scholars agree that the empire''s collapse was not a sudden event but a gradual erosion spanning several decades.', $lyceon_json$[{"key":"A","text":"Nonetheless,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Specifically,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two scholars who disagree about the primary cause of the Khmer Empire''s decline, then notes a point on which they concur. "Nonetheless" correctly signals that despite their disagreement, they share common ground on the timeline. "Consequently" implies the agreement follows logically from the disagreement, but shared conclusions do not result from differing premises. "Specifically" would narrow the preceding point, yet the final sentence broadens to an area of consensus rather than elaborating on one scholar''s argument. "Similarly" suggests the final sentence parallels one of the prior claims, but the sentence introduces shared agreement that contrasts with the preceding disagreement.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T935P2', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary about the composer Florence Price for a music history class. The student wants to present Price''s significance by highlighting both her historical barriers and her musical achievements. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TNZVRS', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Rina Okafor has documented that deep-sea bioluminescent organisms use light emissions primarily for predator evasion rather than prey attraction. Her colleague Pavel Marchenko''s research on the same species, conducted under controlled laboratory conditions, corroborates this finding but also reveals that bioluminescence intensity varies with water pressure. _______ Marchenko''s work suggests that field observations alone may underestimate the range of functions bioluminescence serves, since pressure-dependent behaviors are difficult to replicate in open-ocean studies.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"Instead,"},{"key":"D","text":"For example,"}]$lyceon_json$::jsonb, 'A', NULL, E'Marchenko''s laboratory work confirms Okafor''s findings and adds the discovery of pressure-dependent variation. The final sentence extends this by drawing an additional implication: field observations may be limited. "Furthermore" correctly signals this additive elaboration. "Nevertheless" implies the final sentence contradicts the prior information, but it builds on rather than opposes Marchenko''s findings. "Instead" suggests the final sentence replaces a previously stated idea, yet no idea is being discarded. "For example" would introduce an illustration of a general claim, but the final sentence presents a broader methodological implication rather than a specific instance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TQDWYN', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in the overall text?', E'Coral reefs support roughly one quarter of all marine species despite covering less than one percent of the ocean floor. Their biological productivity rivals that of tropical rainforests, and the economic services they provide — coastal protection, fisheries, tourism — are valued at hundreds of billions of dollars annually.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UC5GAN', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Microbiologist Dara Henriksen has investigated a strain of Bacillus bacteria that, when embedded in concrete during mixing, remains dormant within the hardened material for years. If a crack forms and water infiltrates, the bacteria activate and metabolize calcium lactate also embedded in the concrete, producing limestone that fills the crack. Henriksen observed, however, that in structures exposed to sustained loads — such as bridge supports bearing continuous traffic — cracks often propagate faster than the bacteria can seal them. She concluded that bacterial self-healing concrete is therefore most suitable for ________', $lyceon_json$[{"key":"A","text":"structures subject to intermittent or low-magnitude stress, where cracks develop gradually enough for bacterial mineralization to keep pace."},{"key":"B","text":"underwater structures, because the constant presence of water ensures that the bacteria remain perpetually active and produce limestone continuously."},{"key":"C","text":"any concrete structure, provided that a sufficiently high concentration of bacteria is embedded during the initial mixing process."},{"key":"D","text":"temporary constructions with limited design lifespans, where long-term crack propagation is not a structural concern."}]$lyceon_json$::jsonb, 'A', NULL, E'Henriksen found that under sustained loads, cracks propagate faster than the bacteria can seal them. The logical inference is that the technology works best where stress is intermittent or low in magnitude, allowing cracks to form slowly enough for bacterial mineralization to fill them before they grow critically. The suggestion about underwater structures overlooks a key detail: the bacteria activate when water enters a crack, but perpetual activation is not the issue — the rate of crack propagation relative to sealing speed is. Constant water exposure does not solve the pacing problem in high-load environments, and the passage does not suggest that keeping bacteria perpetually active is desirable or even possible. The claim that any structure would benefit if enough bacteria were added ignores Henriksen''s finding that the fundamental constraint is crack propagation speed, not bacterial concentration. The inference about temporary constructions introduces a consideration (limited lifespan) that the passage does not address; Henriksen''s concern is crack growth rate, not the building''s intended duration of use.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ULJZ2M', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'The hagfish, a jawless marine organism that has persisted largely unchanged for over 300 million years, possesses a remarkable defense mechanism: when seized by a predator, it exudes copious quantities of slime from roughly 150 glands distributed along its body. This slime, composed of mucin and protein threads thinner than a human hair, rapidly expands upon contact with seawater, clogging the gills and mouth of the attacker. Most predators release the hagfish within seconds. Researchers studying this secretion have noted that the protein threads possess a tensile strength comparable to that of spider silk, prompting interest in biomimetic textile applications.', $lyceon_json$[{"key":"A","text":"The hagfish's slime serves as a highly effective antipredator defense and has attracted scientific interest for its material properties."},{"key":"B","text":"Hagfish are among the oldest living vertebrate lineages and have never needed to evolve beyond their current body plan."},{"key":"C","text":"Predators in marine environments have developed few effective strategies for coping with hagfish slime."},{"key":"D","text":"Scientists have successfully created synthetic textiles modeled on hagfish slime proteins."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on two connected points: the hagfish uses slime as a defense mechanism against predators, and the slime''s protein threads have drawn research interest for potential textile applications. The answer stating both the defensive function and scientific interest captures this dual focus. The claim that hagfish never needed to evolve beyond their current body plan overstates what the passage says; it mentions the hagfish has persisted largely unchanged but does not claim evolution was unnecessary. The suggestion that predators have developed few strategies against slime goes beyond the text, which discusses only the slime''s effectiveness without addressing predator countermeasures. The assertion that synthetic textiles have been successfully created is unsupported; the passage mentions only interest in biomimetic applications, not actual products.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WEN41G', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The seeds of many temperate wildflower species require a prolonged period of cold, moist conditions — known as stratification — before they will germinate. This requirement prevents seeds from sprouting during brief warm spells in late autumn or midwinter, which would expose fragile seedlings to subsequent freezing temperatures. Horticulturists who wish to grow these species from seed in controlled greenhouse environments must therefore ________', $lyceon_json$[{"key":"A","text":"simulate winter conditions by refrigerating the seeds for several weeks before planting them."},{"key":"B","text":"harvest seeds exclusively during the summer months when they are most viable."},{"key":"C","text":"plant seeds at greater depths to insulate them from temperature fluctuations."},{"key":"D","text":"select cultivars that have been bred to germinate without exposure to cold."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that these seeds require prolonged cold, moist conditions before germinating. In a controlled greenhouse where natural winter does not occur, horticulturists would need to replicate those conditions artificially — refrigerating seeds for several weeks accomplishes this. The claim about harvesting seeds exclusively in summer introduces a consideration not addressed in the passage, which discusses germination requirements rather than harvest timing. Planting at greater depths addresses insulation but not the specific requirement for cold exposure that triggers germination. Selecting cultivars bred to skip cold requirements is a possible strategy but does not follow from the passage''s logic about growing species that do require stratification; it sidesteps the issue rather than addressing it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YDZO2O', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The 1927 Solvay Conference, at which physicists including Niels Bohr, Werner Heisenberg, and Max Born debated the implications of the newly formulated uncertainty _______ is widely regarded as one of the most consequential scientific gatherings of the twentieth century.', $lyceon_json$[{"key":"A","text":"principle, is"},{"key":"B","text":"principle; is"},{"key":"C","text":"principle. Is"},{"key":"D","text":"principle, it is"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is "The 1927 Solvay Conference," and the verb is "is widely regarded." The intervening nonrestrictive clause ("at which physicists...uncertainty principle") must be closed with a comma before the main verb resumes. A semicolon would incorrectly sever the subject from its verb. A period would create a sentence fragment beginning with "Is widely regarded." Inserting "it" after the comma introduces a redundant subject and creates a comma splice between two independent clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YKG0S2', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The decision by the consortium of nine European universities to pool their computational resources, along with the substantial funding provided by two private technology _______ expected to accelerate the timeline for completing the protein-folding simulation from an estimated seven years to fewer than three.', $lyceon_json$[{"key":"A","text":"foundations, are"},{"key":"B","text":"foundations, were"},{"key":"C","text":"foundations, is"},{"key":"D","text":"foundations, have been"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject is the singular noun "decision." The intervening phrases ("by the consortium of nine European universities," "to pool their computational resources," and "along with the substantial funding provided by two private technology foundations") do not change the number of the subject. The phrase "along with" is a prepositional addition, not a coordinating conjunction, so it does not create a compound subject. The singular present-tense "is" correctly agrees with "decision." The plural forms "are" and "have been" incorrectly treat the nearby plural nouns as the subject. The past-tense "were" is both plural and introduces an unsupported tense shift.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-28"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-28","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
